package org.apache.commons.math.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Comparator;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.ConvergenceException;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.optimization.ConvergenceChecker;
import org.apache.commons.math.optimization.GoalType;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.NotImplementedException;
import org.apache.commons.math3.optimization.univariate.GoalType;
import org.apache.commons.math3.optimization.univariate.UnivariateRealFunction;
import org.apache.commons.math3.optimization.univariate.UnivariateRealPointValuePair;
import org.apache.commons.math3.random.JDKRandomGenerator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for MultiStartUnivariateRealOptimizer.optimize
 */
public class MultiStartUnivariateRealOptimizer_optimize_TriageGen1Test {

    private BaseUnivariateRealOptimizer<UnivariateRealFunction> mockOptimizer;
    private MultiStartUnivariateRealOptimizer optimizer;
    private final int starts = 3;
    private final JDKRandomGenerator randomGenerator = new JDKRandomGenerator();

    @Before
    public void setUp() {
        mockOptimizer = mock(BaseUnivariateRealOptimizer.class);
        optimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, starts, randomGenerator);
    }

    @Test
    public void testOptimize_Minimization() throws FunctionEvaluationException {
        // Arrange
        UnivariateRealFunction function = x -> Math.pow(x - 2.0, 2);
        double min = 0.0;
        double max = 5.0;
        GoalType goal = GoalType.MINIMIZE;

        UnivariateRealPointValuePair expectedResult = new ArrayUnivariateRealPointValuePair(2.0, 0.0);

        // The optimize(f, goal, min, max) calls optimize(f, goal, min, max, 0)
        // We mock the 5-parameter version which is the actual implementation target
        when(mockOptimizer.optimize(function, goal, min, max, 0.0)).thenReturn(expectedResult);

        // Act
        UnivariateRealPointValuePair result = optimizer.optimize(function, goal, min, max);

        // Assert
        assertNotNull(result);
        assertEquals(2.0, result.getPoint(), 1e-10);
        assertEquals(0.0, result.getValue(), 1e-10);
    }

    @Test
    public void testOptimize_Maximization() throws FunctionEvaluationException {
        // Arrange
        UnivariateRealFunction function = x -> -(Math.pow(x - 3.0, 2));
        double min = 0.0;
        double max = 5.0;
        GoalType goal = GoalType.MAXIMIZE;

        UnivariateRealPointValuePair expectedResult = new ArrayUnivariateRealPointValuePair(3.0, 0.0);

        when(mockOptimizer.optimize(function, goal, min, max, 0.0)).thenReturn(expectedResult);

        // Act
        UnivariateRealPointValuePair result = optimizer.optimize(function, goal, min, max);

        // Assert
        assertNotNull(result);
        assertEquals(3.0, result.getPoint(), 1e-10);
        assertEquals(0.0, result.getValue(), 1e-10);
    }

    @Test(expected = FunctionEvaluationException.class)
    public void testOptimize_ThrowsFunctionEvaluationException() throws FunctionEvaluationException {
        // Arrange
        UnivariateRealFunction function = x -> {
            throw new FunctionEvaluationException(new RuntimeException("Eval failed"));
        };
        double min = 0.0;
        double max = 5.0;
        GoalType goal = GoalType.MINIMIZE;

        // Force the mock to throw the exception
        when(mockOptimizer.optimize(function, goal, min, max, 0.0))
            .thenThrow(new FunctionEvaluationException(new RuntimeException("Eval failed")));

        // Act
        optimizer.optimize(function, goal, min, max);
    }

    /**
     * Helper class to satisfy the return type in tests
     */
    private static class ArrayUnivariateRealPointValuePair implements UnivariateRealPointValuePair {
        private final double point;
        private final double value;

        public ArrayUnivariateRealPointValuePair(double point, double value) {
            this.point = point;
            this.value = value;
        }

        @Override
        public double getPoint() { return point; }

        @Override
        public double getValue() { return value; }
    }
}
